\"\"\"OpenAI Responses API client using only the Python standard library.

This module provides a minimal wrapper around the OpenAI *Responses* API
("'`POST https://api.openai.com/v1/responses`) that sends a private text prompt
and returns the generated text. It intentionally avoids any third‑party
dependencies and relies on ``urllib.request`` for HTTP communication.

Typical usage::

    from openai_client import OpenAIResponseClient

    client = OpenAIResponseClient(api_key="sk-…")
    reply = client.send_prompt("Hello, world!")
    print(reply)

The ``api_key`` can also be read from the ``OPENAI_API_KEY`` environment
variable if omitted.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Optional


class OpenAIResponseClient:
    """Simple client for the OpenAI Responses API.

    The client sends a JSON payload containing a ``prompt`` and returns the
    ``text`` field from the response. Errors raise ``RuntimeError`` with a
    helpful message.
    """

    _DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"

    def __init__(self, api_key: [REDACTED_SECRET] = None, endpoint: Optional[str] = None) -> None:
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise RuntimeError("OpenAI API key not provided; set OPENAI_API_KEY env var or pass api_key")
        self.endpoint = endpoint or self._DEFAULT_ENDPOINT

    def _request(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            self.endpoint,
            data=data,
            method="POST",
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
            },
        )
        try:
            with urllib.request.urlopen(req) as resp:
                resp_data = resp.read().decode("utf-8")
                return json.loads(resp_data)
        except urllib.error.HTTPError as e:
            try:
                error_body = e.read().decode()
                detail = json.loads(error_body).get("error", {}).get("message", error_body)
            except Exception:
                detail = e.reason
            raise RuntimeError(f"OpenAI API request failed ({e.code}): {detail}") from None
        except urllib.error.URLError as e:
            raise RuntimeError(f"Failed to reach OpenAI API: {e.reason}") from None

    def send_prompt(self, prompt: str) -> str:
        """Send *prompt* to the Responses API and return the generated text.

        The request payload follows the minimal schema required by the API:
        ``{"model": "gpt-4o-mini", "prompt": prompt}``. Adjust the model name
        as needed for your account.
        """
        if not isinstance(prompt, str):
            raise TypeError("prompt must be a string")

        payload = {
            "model": "gpt-4o-mini",
            "prompt": prompt,
        }
        response = self._request(payload)
        if isinstance(response, dict):
            choices = response.get("choices") or []
            if choices:
                message = choices[0].get("message") or {}
                if "content" in message:
                    return message["content"]
                if "text" in choices[0]:
                    return choices[0]["text"]
            if "response" in response:
                return str(response["response"])
        raise RuntimeError("Unexpected response format from OpenAI API")


def _demo() -> None:
    """Simple command‑line demo executed when the module is run directly.

    Reads a prompt from STDIN (or the first command‑line argument) and prints
    the model'"'s reply.
    \"\"\"
    client = OpenAIResponseClient()
    if len(sys.argv) > 1:
        prompt = \" \".join(sys.argv[1:])
    else:
        prompt = sys.stdin.read().strip()
    if not prompt:
        print(\"Usage: python -m openai_client \\\"Your prompt\\\"\", file=sys.stderr)
        sys.exit(1)
    try:
        reply = client.send_prompt(prompt)
        print(reply)
    except RuntimeError as exc:
        print(f\"Error: {exc}\", file=sys.stderr)
        sys.exit(1)

if __name__ == \"__main__\":
    _demo()
EOF"

